         call nonlocal_pcm_point_mf_medium(state, eps, eps_inf, lam, eps_solute, error)
         return
      end if
      stat = 0
      npt = state%npt
      if (state%ready < 1) then
         call fatal_error(error, &
                          "[nonlocal_pcm_point_medium] call nonlocal_pcm_point_assemble first")
         return
      end if
      state%ready = 1

      state%lam = lam
      state%eps_inf = eps_inf
      state%eps = eps
      state%eps_solute = eps_solute
      state%op1%npt = 3*npt
      state%op1%npoint = npt
      state%op1%id = 1
      state%op1%points => state%r
      state%s7 = 1.0_wp/state%lam
      state%s8 = 1.0_wp/state%eps_inf
      state%s9 = state%s8*state%eps
      state%s10 = sqrt(state%s9)
      !$omp parallel do schedule(dynamic, 16) &
      !$omp& private(i) &
      !$omp& shared(npt, state)
      do j = 1, npt
         block
            real(wp) :: tmp1, tmp2, tmp3, tmp4, tmp5, tmp6, tmp7, tmp8, tmp9, tmp10, tmp11, tmp12, &
                        tmp13, tmp14, tmp15, tmp16, tmp17, tmp18, tmp19, tmp20, tmp21, tmp22, &
                        tmp23, tmp24, tmp25, tmp26, tmp27, tmp28, tmp29, tmp30, tmp31, tmp32, &
                        tmp33, tmp34, tmp35, tmp36, tmp37, tmp38, tmp39, tmp40, tmp41, tmp42, &
                        tmp43

            do i = 1, j - 1
               tmp1 = -state%s2(j)
               tmp2 = state%s2(i) + tmp1
