               tmp4 = -state%s3(j)
               tmp5 = state%s3(i) + tmp4
               tmp6 = tmp5*state%s4(j)
               tmp7 = tmp3 + tmp6
               tmp8 = -state%s5(j)
               tmp9 = state%s5(i) + tmp8
               tmp10 = tmp9*state%s6(j)
               tmp11 = tmp7 + tmp10
               tmp12 = tmp2**(2)
               tmp13 = tmp5**(2)
               tmp14 = tmp12 + tmp13
               tmp15 = tmp9**(2)
               tmp16 = tmp14 + tmp15
               tmp17 = 1.0_wp/sqrt(tmp16)
               tmp18 = tmp17**(3)
               tmp19 = tmp11*tmp18
               tmp20 = sqrt(tmp16)
               tmp21 = state%s7*tmp20
               tmp22 = tmp21*state%s10
               tmp23 = -tmp22
               tmp24 = exp(tmp23)
               tmp25 = 1.0_wp + tmp22
               tmp26 = tmp24*tmp25
               tmp27 = -tmp26
               tmp28 = 1.0_wp + tmp27
               tmp29 = tmp19*tmp28
               tmp30 = tmp29*state%a(j)
               tmp31 = -tmp30
               state%s11(i, j) = tmp31
               tmp32 = -tmp2
               tmp33 = state%s1(i)*tmp32
               tmp34 = -tmp5
               tmp35 = tmp34*state%s4(i)
               tmp36 = tmp33 + tmp35
               tmp37 = -tmp9
               tmp38 = tmp37*state%s6(i)
               tmp39 = tmp36 + tmp38
               tmp40 = tmp39*tmp18
               tmp41 = tmp40*tmp28
               tmp42 = tmp41*state%a(i)
               tmp43 = -tmp42
               state%s11(j, i) = tmp43
            end do
         end block
      end do
      !$omp end parallel do
      do i = 1, npt
         state%s11(i, i) = 0.0_wp
      end do
      state%op1%c1 => state%s11
      state%op1%c2 => state%s12
      state%s13 = 1.0_wp/state%eps
      tmp44 = -state%s13
      state%s14 = state%s8 + tmp44
      state%s15 = state%eps_solute*state%s14
      state%op1%c3 = state%s15
      !$omp parallel do schedule(dynamic, 16) &
      !$omp& private(i) &
      !$omp& shared(npt, state)
      do j = 1, npt
         block
            real(wp) :: tmp45, tmp46, tmp47, tmp48, tmp49, tmp50, tmp51, tmp52, tmp53, tmp54, &
                        tmp55, tmp56, tmp57, tmp58, tmp59, tmp60, tmp61, tmp62, tmp63, tmp64, &
                        tmp65

            do i = 1, j - 1
               tmp45 = -state%s2(j)
               tmp46 = state%s2(i) + tmp45
               tmp47 = tmp46**(2)
               tmp48 = -state%s3(j)
               tmp49 = state%s3(i) + tmp48
               tmp50 = tmp49**(2)
               tmp51 = tmp47 + tmp50
               tmp52 = -state%s5(j)
               tmp53 = state%s5(i) + tmp52
               tmp54 = tmp53**(2)
               tmp55 = tmp51 + tmp54
               tmp56 = sqrt(tmp55)
               tmp57 = state%s7*tmp56
               tmp58 = tmp57*state%s10
               tmp59 = -tmp58
               tmp60 = exp(tmp59)
               tmp61 = tmp60 - 1.0_wp
               tmp62 = 1.0_wp/sqrt(tmp55)
               tmp63 = tmp61*tmp62
               tmp64 = tmp63*state%a(j)
               state%s16(i, j) = tmp64
               tmp65 = tmp63*state%a(i)
               state%s16(j, i) = tmp65
            end do
         end block
      end do
      !$omp end parallel do
      do i = 1, npt
         tmp66 = state%s7*state%a(i)
         tmp67 = tmp66*state%s10
         tmp68 = -tmp67
         state%s16(i, i) = tmp68
      end do
      state%op1%c4 => state%s16
      state%s17 = state%s8*state%eps_solute
      state%op1%c5 = state%s17
      state%op1%c6 => state%s18
      state%s19 = state%s13*state%eps_inf
      state%op1%c7 = state%s19
      call state%solver%setup(state%op1, error)
      if (allocated(error)) return
      tmp69 = state%eps_solute*state%s13
      tmp70 = -tmp69
      state%s20 = 1.0_wp + tmp70
      state%s22 = -state%s15
      state%s24 = -state%s17
      state%s25 = 1.0_wp + state%s24

      state%ready = 2
   end subroutine nonlocal_pcm_point_medium

   !> Nonlocal PCM (point charges): energy, solution and gradient for v, vn
   !>
   !> - Repeat with new inputs as often as needed; the operators are reused
   !> - Needs nonlocal_pcm_point_medium on the same state first
   !> - Vectors have length npt, matrices are (npt, npt), point fields (3, npt)
   !> - Outputs are undefined if error is allocated
