      state%op1%points => state%r
      state%op1%c1 => state%s11
      state%op1%c2 => state%s12
      state%op1%c4 => state%s16
      state%op1%c6 => state%s18
      state%v = v
      state%vn = vn
      call gemv(state%s11, state%v, state%s21)
      call gemv(state%s16, state%vn, state%s23)
      call gemv(state%s18, state%vn, state%s26)
