      call state%solver%solve(state%op1, .false., tmp6, tmp7, error)
      if (allocated(error)) return
      state%s27 = tmp7(npt + 1:2*npt)
      state%s28 = tmp7(1:npt)
      state%s29 = tmp7(2*npt + 1:3*npt)
      state%s30 = (-0.039788735772973836_wp)*state%vn
      state%s31 = 0.039788735772973836_wp*state%v
      tmp8 = state%s30*state%a
      tmp9 = state%s31*state%a
      tmp10(1:npt) = tmp8
      tmp10(npt + 1:2*npt) = tmp9
      tmp10(2*npt + 1:3*npt) = 0.0_wp
      call state%solver%solve(state%op1, .true., tmp10, state%s32, error)
      if (allocated(error)) return
      state%s33 = state%s32(1:npt)
      state%s34 = state%s20*state%s33
      state%s35 = state%s25*state%s33
      state%s36 = state%s22*state%s33
