      state%op1%c2 => state%s12
      state%op1%c4 => state%s16
      state%op1%c6 => state%s18
      call gemv(state%s11, dv, tmp1)
      tmp2 = state%s20*tmp1
      call gemv(state%s16, dvn, tmp3)
      tmp4 = state%s22*tmp3
      tmp5 = tmp2 + tmp4
      call gemv(state%s18, dvn, tmp6)
      tmp7 = state%s25*tmp6
      tmp8 = tmp5 + tmp7
      tmp9(1:npt) = tmp8
      tmp9(npt + 1:2*npt) = 0.0_wp
      tmp9(2*npt + 1:3*npt) = 0.0_wp
      tmp10 = 0.0_wp
      call state%solver%solve(state%op1, .false., tmp9, tmp10, error)
      if (allocated(error)) return
      tmp11 = tmp10(npt + 1:2*npt)
      tmp12 = state%a*tmp11
      tmp13 = 0.039788735772973836_wp*tmp12
      tmp14 = (-0.039788735772973836_wp)*dvn
